783	export async function serverAction(serverId: string, action: string): Promise<{ error?: string } | void> {
784	  // Returns `{ error }` for anything the CUSTOMER can act on, so ServerControls
785	  // can render it — a `throw` here reaches the browser as Next's redacted generic
786	  // error, discarding the specific, actionable message (e.g. "Delete your data
787	  // volume(s) before reinstalling"). Only genuinely-impossible states still throw.
788	  const { user, server } = await ownedServer(serverId);
789	  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
790	    start: "START",
791	    stop: "STOP",
792	    reboot: "REBOOT",
793	    reinstall: "REINSTALL",
794	    delete: "DELETE",
795	  };
796	  const type = allowed[action];
797	  if (!type) throw new Error("Invalid action"); // not reachable from the UI — a real bug if it happens
798	  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
799	    return { error: "This server is suspended. Settle the outstanding balance to control it again." };
800	  }
801	
802	  // A reinstall wipes the whole VM, including any block-storage volume the VM
803	  // owns (Proxmox `qm destroy --purge` frees every disk for that vmid).
804	  //
805	  // Count volumes by `serverId` ALONE, never by `status: "ATTACHED"`. Detaching
806	  // deliberately keeps `serverId` set so the volume can be re-attached
807	  // (worker/volumes.ts) — the disk stays owned by this vmid as an `unusedN`
808	  // entry, and PVE's destroy_vm frees unused disks too (include_unused => 1).
809	  // Filtering on ATTACHED therefore missed the worst case: customer fills a
810	  // volume, clicks Detach (the UI promises "Data is preserved."), clicks
811	  // Reinstall — both guards see zero attached volumes, and the purge takes the
812	  // data with it. `reinstallToOs` in actions-server-lifecycle.ts always counted
813	  // by serverId; this path did not. That asymmetry was the bug.
814	  if (type === "REINSTALL") {
815	    const pinnedVolumes = await db.volume.count({ where: { serverId } });
816	    if (pinnedVolumes > 0) {
817	      return {
818	        error:
819	          "Delete your data volume(s) before reinstalling — a reinstall wipes the whole server, and that includes detached volumes still assigned to it. Open Volumes first.",
820	      };
821	    }
822	  }
823	
824	  const pending = await db.job.count({
825	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
826	  });
827	  // Was a silent `return`: the customer clicked Start and nothing happened, ever,
828	  // with no explanation. Tell them why.
829	  if (pending > 0) return { error: "Another operation is already running on this server. Wait for it to finish." };
830	
831	  if (type === "DELETE") {
832	    await db.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
833	  }
834	  await db.job.create({ data: { type, serverId } });
835	  await audit(user.id, `server.${action}`, serverId);
836	  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
837	  revalidatePath(`/dashboard/servers/${serverId}`);
838	}
