88	/** Resolve the game family (game plan first, then OS template) if it is a game. */
89	function resolveFamily(server: {
90	  osTemplate?: { family?: string | null } | null;
91	  gamePlan?: { gameFamily?: string | null } | null;
92	}): string | null {
93	  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
94	  return isGameFamily(fam) ? fam : null;
95	}
