97	function requireSpec(server: Parameters<typeof resolveFamily>[0]): GameControlSpec {
98	  const family = resolveFamily(server);
99	  const spec = controlSpec(family);
100	  if (!spec) throw new Error("This server is not a supported game server.");
101	  return spec;
102	}
