109	async function lifecycleBusy(serverId: string): Promise<boolean> {
110	  const n = await db.job.count({
111	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: { in: EXCLUSIVE_JOBS as any } },
112	  });
113	  return n > 0;
