116	async function gameJobInflight(serverId: string): Promise<boolean> {
117	  const n = await db.job.count({
118	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: { in: ["GAME_POWER", "GAME_BACKUP", "GAME_REINSTALL"] as any } },
119	  });
120	  return n > 0;
