123	/** Never surface credentials or internal detail in a customer-facing error. */
124	function safeError(err: unknown): string {
125	  const msg = err instanceof Error ? err.message : String(err);
126	  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
127	  if (/not a supported game server|not enabled|not available|not running|in progress/i.test(msg)) return msg.slice(0, 200);
128	  if (/timed out|reachable|root password/i.test(msg)) return msg.slice(0, 200);
129	  return "Could not reach the game server. Please try again shortly.";
130	}
