178	export async function gamePower(serverId: string, action: string): Promise<Result> {
179	  try {
180	    const { user, server } = await ownedServer(serverId);
181	    requireSpec(server);
182	    if (!isPowerAction(action)) return { ok: false, error: "Unsupported action." };
183	    const limited = throttle(user.id, "power", 20);
184	    if (limited) return { ok: false, error: limited };
185	    if (server.status !== "RUNNING")
186	      return { ok: false, error: "The VM must be running to control the game service." };
187	    if (await lifecycleBusy(server.id))
188	      return { ok: false, error: "Another server operation is in progress — try again shortly." };
189	    if (await gameJobInflight(server.id))
190	      return { ok: false, error: "A game control action is already in progress on this server." };
191	
192	    await db.job.create({
193	      data: { type: "GAME_POWER", serverId: server.id, payload: { action, announce: action === "restart" } },
194	    });
195	    await db.auditLog.create({
196	      data: { userId: user.id, action: "gameserver.power", detail: `${action} on ${server.hostname}` },
197	    });
198	    revalidatePath(`/dashboard/servers/${serverId}`);
199	    return { ok: true };
200	  } catch (err) {
201	    return { ok: false, error: safeError(err) };
202	  }
203	}
