210	/**
211	 * Wipe this server's game data and re-run its setup script against the SAME
212	 * VM — enqueues GAME_REINSTALL. Requires the literal confirmation text
213	 * "WIPE" (case-insensitive) since this permanently destroys the world/save
214	 * data with no undo, the same discipline `reinstallToOs`'s "ERASE" confirm
215	 * uses for the VPS-level equivalent.
216	 *
217	 * Deliberately does NOT support switching to a different game family — that
218	 * needs a different OsTemplate/GamePlan/ports/RCON setup and is real,
219	 * separable work; see gameReinstall's own doc comment. This only ever
220	 * reinstalls the CURRENT family.
221	 */
222	export async function reinstallGame(serverId: string, confirmText: string): Promise<Result> {
223	  try {
224	    const { user, server } = await ownedServer(serverId);
225	    const spec = requireSpec(server);
226	    if (confirmText.trim().toUpperCase() !== "WIPE") {
227	      return { ok: false, error: 'Type "WIPE" to confirm.' };
228	    }
229	    const limited = throttle(user.id, "reinstall", 3);
230	    if (limited) return { ok: false, error: limited };
231	    if (server.status !== "RUNNING")
232	      return { ok: false, error: "The VPS must be running to reinstall the game." };
233	    if (await lifecycleBusy(server.id))
234	      return { ok: false, error: "Another server operation is in progress — try again shortly." };
235	    if (await gameJobInflight(server.id))
236	      return { ok: false, error: "A game control action is already in progress on this server." };
237	
238	    await db.job.create({ data: { type: "GAME_REINSTALL", serverId: server.id } });
239	    await db.auditLog.create({
240	      data: { userId: user.id, action: "gameserver.reinstall", detail: `${spec.family} on ${server.hostname}` },
241	    });
242	    revalidatePath(`/dashboard/servers/${serverId}`);
243	    return { ok: true };
244	  } catch (err) {
245	    return { ok: false, error: safeError(err) };
246	  }
247	}
