24	export function VpsPowerControls({ serverId, serverName, status, busy, terminalSlot }: {
25	  serverId: string;
26	  serverName: string;
27	  status: string;
28	  busy: boolean;
29	  /** The existing OpenTerminalButton — primary action. */
30	  terminalSlot: React.ReactNode;
31	}) {
32	  const [error, setError] = useState<string | null>(null);
33	  const [ask, setAsk] = useState<"reinstall" | "delete" | "stop" | null>(null);
34	  const [pending, start] = useTransition();
35	  const disabled = pending || busy;
36	  const running = status === "RUNNING";
37	
38	  const run = (action: string) => {
39	    setError(null);
40	    start(async () => {
41	      const res = await serverAction(serverId, action);
42	      if (res?.error) setError(res.error);
43	    });
44	  };
45	
46	  /* Each action reads as itself: reboot is amber-tinted caution, stop is
47	     rose, start is the go action, More is neutral. A row of five identical
48	     grey buttons is what made Delete look as routine as Reboot. */
49	  const base =
50	    "inline-flex items-center gap-1.5 rounded-[10px] border px-3.5 py-2 text-[12.5px] font-bold transition disabled:opacity-40 disabled:cursor-not-allowed";
51	  const amber = `${base} border-amber-400/35 bg-amber-500/[0.10] text-amber-200 hover:border-amber-400/60 hover:bg-amber-500/[0.16]`;
52	  const rose  = `${base} border-rose-400/35 bg-rose-500/[0.10] text-rose-200 hover:border-rose-400/60 hover:bg-rose-500/[0.16]`;
53	  const mint  = `${base} border-emerald-400/35 bg-emerald-500/[0.10] text-emerald-200 hover:border-emerald-400/60 hover:bg-emerald-500/[0.16]`;
54	
55	  return (
56	    <div className="flex flex-none flex-col items-end gap-2">
57	      <div className="flex flex-wrap items-center gap-2">
58	        {terminalSlot}
59	
60	        {!running && (
61	          <button type="button" disabled={disabled} onClick={() => run("start")} className={mint}>
62	            <Icon name="bolt" size={14} tone="inherit" /> Start
63	          </button>
64	        )}
65	        {running && (
66	          <>
67	            <button type="button" disabled={disabled} onClick={() => run("reboot")} className={amber}>
68	              <Icon name="refresh" size={14} tone="inherit" /> Reboot
69	            </button>
70	            <button type="button" disabled={disabled} onClick={() => setAsk("stop")} className={rose}>
71	              <Icon name="xcircle" size={14} tone="inherit" /> Stop
72	            </button>
73	          </>
74	        )}
75	
76	        <Menu
77	          label="More"
78	          items={[
79	            { key: "reinstall", label: "Reinstall OS…", icon: "refresh2", danger: true, onSelect: () => setAsk("reinstall") },
80	            { key: "delete", label: "Delete server…", icon: "trash", danger: true, onSelect: () => setAsk("delete") },
81	          ]}
82	        />
83	      </div>
84	
85	      {error && (
86	        <p className="text-[11.5px] text-rose-300" role="alert">{error}</p>
87	      )}
88	
89	      {/* Disabled controls with no stated reason are the worst kind: the
90	          customer cannot tell a broken button from a busy one. */}
91	      {busy && !error && (
92	        <p className="flex items-center gap-1.5 text-[11.5px] text-tx-faint">
93	          <Icon name="refresh2" size={12} className="nx-spin" />
94	          A job is running on this server — power controls come back when it finishes.
95	        </p>
96	      )}
97	
98	      {/* Stopping is reversible, so it asks once without ceremony. */}
99	      <Confirm
100	        open={ask === "stop"}
101	        title="Stop this server?"
102	        body="It will power off until you start it again. Anything running inside stops with it."
103	        confirmLabel="Stop server"
104	        onConfirm={() => run("stop")}
105	        onClose={() => setAsk(null)}
106	      />
107	
108	      <Confirm
109	        open={ask === "reinstall"}
110	        danger
111	        typeToConfirm={serverName}
112	        title="Reinstall the operating system?"
113	        body={
114	          <>
115	            This wipes <span className="font-bold text-tx">everything</span> on the disk and
116	            redeploys a fresh OS. Files, databases, configuration and installed software are all
117	            destroyed. Backups taken before now are unaffected.
118	          </>
119	        }
120	        confirmLabel="Wipe and reinstall"
121	        onConfirm={() => run("reinstall")}
122	        onClose={() => setAsk(null)}
123	      />
124	
125	      <Confirm
126	        open={ask === "delete"}
127	        danger
128	        typeToConfirm={serverName}
129	        title="Delete this server permanently?"
130	        body={
131	          <>
132	            The machine and its disk are destroyed and cannot be recovered — not by us, not from a
133	            snapshot. Any remaining term is handled by the cancellation flow under Settings, which
134	            shows your refund first.
135	          </>
136	        }
137	        confirmLabel="Delete permanently"
138	        onConfirm={() => run("delete")}
139	        onClose={() => setAsk(null)}
140	      />
141	    </div>
142	  );
143	}
