18	 * with a synthetic sine wave so they "always looked alive" before RRD arrived —
19	 * that is a drawing of data that does not exist, so a server with no history
20	 * now shows a flat baseline and says so instead.
21	 */
22	
23	const STATUS: Record<string, { dot: string; ring: string; ink: string; label: string }> = {
24	  RUNNING:      { dot: "bg-emerald-400", ring: "border-emerald-400/40 bg-emerald-950/60", ink: "text-emerald-300", label: "Online" },
25	  STOPPED:      { dot: "bg-rose-400",    ring: "border-rose-400/40 bg-rose-950/60",       ink: "text-rose-300",    label: "Offline" },
26	  SUSPENDED:    { dot: "bg-orange-400",  ring: "border-orange-400/40 bg-orange-950/60",   ink: "text-orange-300",  label: "Suspended" },
27	  PROVISIONING: { dot: "bg-sky-400 animate-pulse", ring: "border-sky-400/40 bg-sky-950/60", ink: "text-sky-300",   label: "Deploying" },
28	  PENDING:      { dot: "bg-sky-400 animate-pulse", ring: "border-sky-400/40 bg-sky-950/60", ink: "text-sky-300",   label: "Deploying" },
29	  REINSTALLING: { dot: "bg-sky-400 animate-pulse", ring: "border-sky-400/40 bg-sky-950/60", ink: "text-sky-300",   label: "Reinstalling" },
30	  ERROR:        { dot: "bg-red-400",     ring: "border-red-400/40 bg-red-950/60",         ink: "text-red-300",     label: "Error" },
31	};
