33	/** A 24-point sparkline, or a flat baseline when there is no history yet. */
34	function Spark({ points, tone }: { points: number[]; tone: string }) {
35	  const W = 96, H = 26;
36	  const has = points.length >= 3;
37	  const src = has ? points : [0, 0];
38	  const max = Math.max(1, ...src);
39	  const step = W / Math.max(1, src.length - 1);
40	  const d = src.map((v, i) => `${i === 0 ? "M" : "L"}${(i * step).toFixed(1)},${(H - (v / max) * (H - 3) - 1.5).toFixed(1)}`).join(" ");
41	  return (
42	    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} className="overflow-visible" aria-hidden>
43	      <path d={d} fill="none" stroke={tone} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"
44	            opacity={has ? 1 : 0.28} />
45	    </svg>
46	  );
47	}
