15	  /** customer-facing server name (label || name) */
16	  name: string;
17	  /** pretty game name, e.g. "Rust", "Minecraft" */
18	  gameLabel: string;
19	  /** raw ServerStatus (RUNNING, STOPPED, …) */
20	  status: string;
21	  running: boolean;
22	  /** ip:port players connect to, or null while provisioning */
23	  connect: string | null;
24	  /** short server id badge, e.g. "#srv_8f7a2c1d" */
25	  serverIdShort: string;
26	  node: string | null;
27	  location: string | null;
28	  /** ISO-3166 alpha-2 for the location flag, or null when unknown. */
29	  locationCountry?: string | null;
30	  players: { online: number; max: number | null };
31	  /** CPU percent 0-100 */
32	  cpuPct: number;
33	  /**
34	   * memory in bytes. usedBytes is NOT Proxmox's live `mem` balloon field —
35	   * that stat is MemFree-based, not MemAvailable-based, so a server with
36	   * ordinary disk/page-cache activity (the game's own world/save files count)
37	   * reads falsely high "memory used" even with plenty of genuinely spare
38	   * RAM. usedBytes comes from ServerMemSample (the worker's periodic
39	   * guest-agent /proc/meminfo read) instead, and is null until a sample has
40	   * landed — maxBytes is always known (provisioned RAM) so it stays plain.
41	   */
42	  mem: { usedBytes: number | null; maxBytes: number };
43	  /** disk in GB */
44	  disk: { usedGB: number; maxGB: number };
45	  /** network throughput, MB/s (null when unknown) */
46	  net: { inMbps: number | null; outMbps: number | null };
47	  uptimeLabel: string;
48	  createdLabel: string;
49	  nextRestartLabel: string | null;
50	  /** power controls are usable (VM steady + not busy) */
51	  canControl: boolean;
52	  /** customer's own domain pointing at this server (null = none set) */
53	  customDomain: string | null;
