3	import { useState, useTransition } from "react";
4	import { serverAction } from "@/lib/actions";
5	
6	export function PowerActions({ serverId, status }: { serverId: string; status: string }) {
7	  const [pending, start] = useTransition();
8	  const [error, setError] = useState<string | null>(null);
9	  const run = (action: "start" | "stop" | "reboot") => {
10	    if (window.confirm(`Send ${action.toUpperCase()} to this server?`)) {
11	      setError(null);
12	      // serverAction returns { error } now — an operator sees why a click did
13	      // nothing instead of silence.
14	      start(async () => {
15	        const res = await serverAction(serverId, action);
16	        if (res?.error) setError(res.error);
17	      });
18	    }
19	  };
20	  const busy = pending || ["PROVISIONING", "REINSTALLING", "DELETING", "PENDING"].includes(status);
21	  return (
22	    <div className="flex flex-col gap-1">
23	      <div className="flex items-center gap-2">
24	        <button className="btn-secondary py-1.5" disabled={busy || status === "RUNNING"} onClick={() => run("start")}>
25	          Start
26	        </button>
27	        <button className="btn-secondary py-1.5" disabled={busy || status === "STOPPED"} onClick={() => run("stop")}>
28	          Stop
29	        </button>
30	        <button className="btn-secondary py-1.5" disabled={busy || status !== "RUNNING"} onClick={() => run("reboot")}>
31	          Reboot
32	        </button>
33	      </div>
34	      {error && <p className="text-xs text-red-400" role="alert">{error}</p>}
35	    </div>
36	  );
37	}
38	
39	/**
40	 * Compact single-action Reboot button for the Server Fleet table row — the
41	 * SAME `serverAction(serverId, "reboot")` server action `PowerActions` above
42	 * calls on the server detail page. `ownedServer()` (lib/actions.ts) already
43	 * lets an ADMIN act on a server it doesn't own, so this needs no new
44	 * mechanism and no impersonation — it's the real, existing admin-safe path.
45	 */
46	export function RebootServerButton({ serverId, status }: { serverId: string; status: string }) {
47	  const [pending, start] = useTransition();
48	  const [error, setError] = useState<string | null>(null);
49	  const disabled = pending || status !== "RUNNING";
50	  return (
51	    <div className="flex flex-col items-end gap-1">
52	      <button
53	        className="btn-ghost py-1 text-xs"
54	        disabled={disabled}
55	        title={status !== "RUNNING" ? "Only a running server can be rebooted" : "Send REBOOT to this server"}
56	        onClick={() => {
57	          if (!window.confirm(`Reboot this server now? Active connections and unsaved in-VM state are lost.`)) return;
58	          setError(null);
59	          start(async () => {
60	            const res = await serverAction(serverId, "reboot");
61	            if (res?.error) setError(res.error);
62	          });
63	        }}
64	      >
65	        {pending ? "Rebooting…" : "Reboot"}
66	      </button>
67	      {error && <span className="text-xs text-red-400">{error}</span>}
68	    </div>
69	  );
70	}
71	
72	export function DangerDelete({ serverId, hostname }: { serverId: string; hostname: string }) {
73	  const [pending, start] = useTransition();
74	  const [confirmText, setConfirmText] = useState("");
75	  const [armed, setArmed] = useState(false);
76	
77	  if (!armed) {
78	    return (
79	      <button className="btn-danger" onClick={() => setArmed(true)}>
80	        Delete server…
81	      </button>
82	    );
83	  }
84	  return (
85	    <div className="flex flex-wrap items-center gap-2">
86	      <input
87	        className="input w-56 py-1.5 font-mono text-xs"
88	        placeholder={`type "${hostname}" to confirm`}
89	        value={confirmText}
90	        onChange={(e) => setConfirmText(e.target.value)}
91	        autoFocus
92	      />
93	      <button
94	        className="btn-danger py-1.5"
95	        disabled={pending || confirmText !== hostname}
96	        onClick={() => {
97	          if (
98	            window.confirm(
99	              // A full delete runs `qm destroy --purge`, which frees EVERY disk the
100	              // vmid owns — including any attached block-storage data volume (billed
101	              // separately) — and the worker then deletes those Volume rows too. The
102	              // reinstall path refuses when volumes exist; delete takes them with it,
103	              // so the operator must be told before, not just notified after.
104	              `Really destroy ${hostname}? The VM, its disk, IP, port forwards AND any attached data volumes (billed separately) are removed permanently. This cannot be undone.`
105	            )
106	          ) {
107	            start(async () => {
108	              // On success serverAction redirects; only a returned error stays here.
109	              const res = await serverAction(serverId, "delete");
110	              if (res?.error) window.alert(res.error);
111	            });
112	          }
113	        }}
114	      >
115	        {pending ? "Deleting…" : "Destroy permanently"}
116	      </button>
117	      <button
118	        className="btn-ghost py-1.5"
119	        onClick={() => {
120	          setArmed(false);
121	          setConfirmText("");
122	        }}
123	      >
124	        Cancel
125	      </button>
126	    </div>
127	  );
128	}
