112	/**
113	 * Build the remote unit-resolution + systemctl script. `hints`/`family` come from
114	 * the family's control spec (compile-time constants); `action` is one of the three
115	 * allowlisted verbs. Emits NXGP markers so a clean SSH exit is never mistaken for
116	 * a successful action (the same discipline as worker/game-update.ts).
117	 */
118	function powerScript(spec: GameControlSpec, action: string): string {
119	  const hints = spec.serviceHints.map(shq).join(" ");
120	  return [
121	    `unit=""`,
122	    `for c in ${hints}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
123	    `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${shq(spec.family)} | head -1 | awk '{print $1}'); fi`,
124	    `if [ -z "$unit" ]; then echo "NXGP:UNIT:NONE"; exit 0; fi`,
125	    `echo "NXGP:UNIT:$unit"`,
126	    `systemctl ${action} "$unit" >/dev/null 2>&1; echo "NXGP:RC:$?"`,
127	    `st=$(systemctl is-active "$unit" 2>/dev/null); echo "NXGP:STATE:${"$"}{st:-unknown}"`,
128	    `echo "NXGP:END"`,
129	  ].join("\n");
130	}
