259	export async function gameBackup(job: Job): Promise<void> {
260	  if (!job.serverId) throw new Error("game backup: missing serverId");
261	  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: CONTROL_FIELDS })) as ControlServer | null;
262	  if (!server) throw new Error(`Server ${job.serverId} not found`);
263	  const spec = resolveSpec(server);
264	  const href = `/dashboard/servers/${server.id}?tab=manage`;
265	
266	  if (SANDBOX) {
267	    await notify(server.userId, `World backup created (sandbox) on ${server.hostname}`, `Sandbox only — no VM was contacted for the ${spec.label} world backup.`, href);
268	    return;
269	  }
270	  if (server.status !== "RUNNING") throw new Error("game backup: VM is not running");
271	
272	  const outcome = await withServerSsh(server as SftpServer, async (conn) => {
273	    const dir = await remoteLocateDir(conn, spec.dataRoots);
274	    if (!dir || !isSafeRemotePath(dir)) return { ok: false, msg: "Could not locate the world/save directory." };
275	    // Timestamped archive under the fixed backup dir. `parent`/`base` are derived
276	    // from the located (allowlisted) dir; every value interpolated is single-quoted.
277	    const ts = new Date().toISOString().replace(/[-:]/g, "").replace(/\..+$/, "").replace("T", "-");
278	    const archive = `${GAME_BACKUP_DIR}/${spec.family}-${ts}.tar.gz`;
279	    const parent = dir.replace(/\/[^/]+$/, "") || "/";
280	    const base = dir.replace(/^.*\//, "");
281	    const script =
282	      `mkdir -p ${shq(GAME_BACKUP_DIR)} && ` +
283	      `tar czf ${shq(archive)} -C ${shq(parent)} ${shq(base)} 2>&1 && ` +
284	      `stat -c '%s' ${shq(archive)}`;
285	    const r = await exec(conn, script, SETUP_TIMEOUT_MS);
286	    if (r.code !== 0) return { ok: false, msg: (r.stderr || r.stdout).trim().slice(0, 200) || "tar failed" };
287	    const size = Number(r.stdout.trim().split(/\r?\n/).pop());
288	    return { ok: true, archive, size: Number.isFinite(size) ? size : 0 };
289	  });
290	
291	  if (!outcome.ok) {
292	    await notify(server.userId, `World backup failed on ${server.hostname}`, outcome.msg, href);
293	    throw new Error(`game backup failed: ${outcome.msg}`);
294	  }
295	  const mb = ((outcome.size ?? 0) / (1024 * 1024)).toFixed(1);
296	  await notify(
297	    server.userId,
298	    `${spec.label} world backup ready on ${server.hostname}`,
299	    `Backed up your world (${mb} MB). Download it from the Manage → Worlds tab.`,
300	    href
301	  );
302	}
