function took(a: string, b: string | null): string | null {
  if (!b) return null;
  const s = Math.round((new Date(b).getTime() - new Date(a).getTime()) / 1000);
  if (s < 0) return null;
  if (s < 60) return `${s}s`;
  if (s < 3600) return `${Math.floor(s / 60)}m ${s % 60}s`;
  return `${Math.floor(s / 3600)}h ${Math.floor((s % 3600) / 60)}m`;
}

