// Staging-only test fixture for the power-control debounce work.
// Creates a throwaway customer + clones one VPS and one Minecraft server row
// (sandboxed staging: fake vmids, no real VM) owned by that customer.
//   node pd-fixture.mjs setup   -> prints JSON {email,password,vpsId,gameId}
//   node pd-fixture.mjs teardown
import { createRequire } from "node:module";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { randomBytes } from "node:crypto";
const require = createRequire("/opt/nxeon/package.json");
const { PrismaClient } = require("@prisma/client");
const bcrypt = require("bcryptjs");

const env = readFileSync("/opt/nxeon-staging/.env", "utf8");
const url = /^DATABASE_URL=(.*)$/m.exec(env)[1].trim().replace(/^"|"$/g, "");
if (!/nxeon_staging/.test(url)) throw new Error("refusing: not the staging DB");
const db = new PrismaClient({ datasources: { db: { url } } });

const EMAIL = "power-debounce-test@nxeon.test";
const STATE = new URL("./pd-fixture.json", import.meta.url).pathname;

async function setup() {
  const password = randomBytes(12).toString("base64url");
  const passwordHash = await bcrypt.hash(password, 12);
  const user = await db.user.upsert({
    where: { email: EMAIL },
    update: { passwordHash, emailVerifiedAt: new Date() },
    create: { email: EMAIL, name: "Power Debounce Test", passwordHash, emailVerifiedAt: new Date() },
  });
  const ids = {};
  for (const [key, src, vmid] of [["vpsId", "vps-72te", 990901], ["gameId", "minecraft-z6eoxp", 990902]]) {
    const host = `pdtest-${src}`;
    const existing = await db.server.findUnique({ where: { hostname: host } });
    if (existing) { ids[key] = existing.id; continue; }
    const id = "pdt" + randomBytes(10).toString("hex");
    await db.$executeRawUnsafe(`
      CREATE TEMP TABLE IF NOT EXISTS pd_clone AS SELECT * FROM "Server" WHERE false;
      `);
    await db.$executeRawUnsafe(`DELETE FROM pd_clone`);
    await db.$executeRawUnsafe(`INSERT INTO pd_clone SELECT * FROM "Server" WHERE hostname = $1`, src);
    await db.$executeRawUnsafe(
      `UPDATE pd_clone SET id=$1, "userId"=$2, hostname=$3, name=$3, label=$4, vmid=$5,
         "ipAddress"=NULL, "sshPort"=NULL, "telemetryTokenHash"=NULL, subdomain=NULL,
         status='RUNNING', "createdAt"=now(), "updatedAt"=now(), "publicListing"=false`,
      id, user.id, host, key === "vpsId" ? "PD test VPS" : "PD test Minecraft", vmid,
    );
    await db.$executeRawUnsafe(`INSERT INTO "Server" SELECT * FROM pd_clone`);
    ids[key] = id;
  }
  const out = { email: EMAIL, password, userId: user.id, ...ids };
  writeFileSync(STATE, JSON.stringify(out, null, 2), { mode: 0o600 });
  console.log(JSON.stringify({ ...out, password: "(saved to pd-fixture.json)" }));
}

async function teardown() {
  const user = await db.user.findUnique({ where: { email: EMAIL } });
  if (!user) return console.log("nothing to tear down");
  const servers = await db.server.findMany({ where: { userId: user.id, hostname: { startsWith: "pdtest-" } } });
  for (const s of servers) {
    await db.job.deleteMany({ where: { serverId: s.id } });
    await db.server.delete({ where: { id: s.id } });
  }
  await db.notification.deleteMany({ where: { userId: user.id } });
  console.log(`removed ${servers.length} server rows (user kept for audit-log FKs)`);
}

const cmd = process.argv[2];
try {
  if (cmd === "setup") await setup();
  else if (cmd === "teardown") await teardown();
  else console.log("usage: setup|teardown");
} finally {
  await db.$disconnect();
}

