input.content:
// Race probe: does the server-side "one in-flight job per server" guard hold
// under truly concurrent requests (two tabs / a script), not just the
// serialized single-tab case?
//   node pd-race.mjs vps|game [N]
// Captures the real Server Action request from one genuine button click, waits
// for that job to finish, then fires N identical requests at once and counts
// how many jobs actually got created.
import { createRequire } from "node:module";
import { readFileSync } from "node:fs";
const require = createRequire("/opt/nxeon/package.json");
const { chromium } = require("playwright");
const { PrismaClient } = require("@prisma/client");

const fx = JSON.parse(readFileSync(new URL("./pd-fixture.json", import.meta.url), "utf8"));
const env = readFileSync("/opt/nxeon-staging/.env", "utf8");
const url = /^DATABASE_URL=(.*)$/m.exec(env)[1].trim().replace(/^"|"$/g, "");
if (!/nxeon_staging/.test(url)) throw new Error("not staging");
const db = new PrismaClient({ datasources: { db: { url } } });
const BASE = "https://staging.nxeon.cloud";
const kind = process.argv[2] ?? "vps";
const N = Number(process.argv[3] ?? 10);
const serverId = kind === "vps" ? fx.vpsId : fx.gameId;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function waitIdle() {
  for (let i = 0; i < 60; i++) {
    const n = await db.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
    if (n === 0) return;
    await sleep(1000);
  }
  throw new Error("server never went idle");
}

const browser = await chromium.launch();
try {
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  await page.goto(`${BASE}/login`, { waitUntil: "domcontentloaded" });
  await page.fill("#login-email", fx.email);
  await page.fill("#login-password", fx.password);
  await Promise.all([page.waitForURL((u) => !u.pathname.startsWith("/login"), { timeout: 30000 }), page.click("button.btn-primary")]);
  await waitIdle();
  await page.goto(`${BASE}/dashboard/servers/${serverId}`, { waitUntil: "networkidle" });

  let captured = null;
  page.on("request", (req) => {
    const h = req.headers();
    if (req.method() === "POST" && h["next-action"] && !captured) {
      captured = { url: req.url(), headers: h, body: req.postData() };
    }
  });
  // One genuine click: VPS "Reboot", game "Restart".
  const label = kind === "vps" ? "Reboot" : "Restart";
  await page.getByRole("button", { name: new RegExp(`^\\s*${label}\\s*$`) }).first().click();
  for (let i = 0; i < 50 && !captured; i++) await sleep(100);
  if (!captured) throw new Error("no server action request captured");
  console.log("captured action", captured.headers["next-action"].slice(0, 12) + "…", "body", captured.body);
  await sleep(1500);
  await waitIdle();
  await sleep(500);

  const before = await db.job.count({ where: { serverId } });
  const t0 = new Date();
  const results = await page.evaluate(async ({ url, headers, body, N }) => {
    const h = { ...headers };
    delete h["content-length"];
    const reqs = Array.from({ length: N }, () =>
      fetch(url, { method: "POST", headers: h, body, credentials: "include" }).then(async (r) => ({ status: r.status, text: (await r.text()).slice(-240) })),
    );
    return Promise.all(reqs);
  }, { ...captured, N });
  const created = await db.job.findMany({ where: { serverId, createdAt: { gte: t0 } }, select: { id: true, type: true, status: true, createdAt: true } });
  const after = await db.job.count({ where: { serverId } });
  const rejected = results.filter((r) => /already (running|in progress)/i.test(r.text)).length;
  console.log(JSON.stringify({ kind, concurrent: N, jobsCreated: created.length, jobsBefore: before, jobsAfter: after, rejectedWithMessage: rejected, httpStatuses: results.map((r) => r.status) }, null, 1));
  if (process.env.SHOW) for (const r of results) console.log(r.text.replace(/\s+/g, " "));
  await waitIdle();
} finally {
  await browser.close();
  await db.$disconnect();
}

