input.content:
/**
 * Power-control state for the customer dashboard's VPS and game heroes.
 *
 * WHY: real customers spam-clicked Start/Stop/Restart because nothing told them
 * an action was genuinely underway — the buttons just faded to 40% opacity with
 * no explanation, the status pill kept saying "Offline" for the minutes a big
 * world takes to load, and when a job ended the buttons silently came back
 * (found via a Terraria customer's report 2026-09-30, alongside the backend
 * false-failure fix in worker/game-control.ts's `powerStartTimeoutMs`).
 *
 * This module turns the server's REAL `Job` rows into a small snapshot the
 * client can render honestly: which power action is in flight, whether it is
 * still queued or actually running, how many attempts the worker has made,
 * how long ago it was requested (measured, never estimated), and — once it
 * ends — whether it succeeded, with a customer-safe explanation if not.
 *
 * Pure and dependency-free: the server page builds the snapshot
 * (`powerSnapshot`), the client heroes consume it through
 * components/customer/power/usePowerGuard.ts. No invented progress: there is
 * no percentage anywhere because the worker has none to give.
 */

export type PowerKind = "vps" | "game";
export type PowerAction = "start" | "stop" | "reboot" | "restart";
export type PowerJobStatus = "QUEUED" | "RUNNING" | "DONE" | "FAILED";

export type PowerJobView = {
  id: string;
  action: PowerAction;
  status: PowerJobStatus;
  /** Worker attempts so far — 0 until first claimed, >1 means it is retrying. */
  attempts: number;
  /** ms between the job being created and the page rendering (server clock). */
  ageMs: number;
  /** ms since a terminal job finished (server clock); null while in flight. */
  finishedAgoMs: number | null;
  /** Customer-safe reason for a FAILED job; null otherwise. */
  failure: string | null;
};

export type PowerSnapshot = {
  /** The power job currently QUEUED/RUNNING for this server, if any. */
  inflight: PowerJobView | null;
  /** The most recent power job that has finished (DONE/FAILED), if any. */
  last: PowerJobView | null;
  /**
   * A NON-power job is in flight. Power controls stay withheld until it ends
   * (the backend refuses them anyway); this is what we tell the customer why.
   */
  blockedBy: string | null;
};

/** The minimal Job shape both dashboards already load (`server.jobs`). */
export type PowerJobRow = {
  id: string;
  type: string;
  status: string;
  attempts: number;
  payload: unknown;
  error: string | null;
  createdAt: Date;
  updatedAt: Date;
};

const VPS_POWER: Record<string, PowerAction> = { START: "start", STOP: "stop", REBOOT: "reboot" };

/** In-progress phrasing for jobs that block power controls without being power. */
const BLOCKING_LABEL: Record<string, string> = {
  PROVISION: "Server setup",
  REINSTALL: "An OS reinstall",
  DELETE: "Server deletion",
  RESIZE: "A plan change",
  START: "A server power-on",
  STOP: "A server power-off",
  REBOOT: "A server reboot",
  SUSPEND: "A suspension",
  UNSUSPEND: "Reactivation",
  SNAPSHOT_CREATE: "A snapshot",
  SNAPSHOT_DELETE: "A snapshot deletion",
  SNAPSHOT_ROLLBACK: "A snapshot rollback",
  BACKUP_CREATE: "A backup",
  BACKUP_RESTORE: "A backup restore",
  SYNC_FORWARDS: "A networking update",
  SYNC_FIREWALL: "A firewall update",
  SYNC_GAME_DNS: "A DNS update",
  PASSWORD_RESET: "A root password reset",
  DISK_EXPAND: "A storage upgrade",
  ASSIGN_DEDICATED_IP: "A dedicated IP assignment",
  MIGRATE: "A migration",
  SSL_ISSUE: "A certificate request",
  GAME_POWER: "A game service power action",
  GAME_BACKUP: "A world backup",
  GAME_REINSTALL: "A game reinstall",
  GAME_UPDATE: "A game update",
  GAME_CONFIG: "Applying game settings",
  GAME_MOD_SYNC: "A mod sync",
};

const IN_FLIGHT = new Set(["QUEUED", "RUNNING"]);
const TERMINAL = new Set(["DONE", "FAILED"]);

export function powerActionOf(kind: PowerKind, job: { type: string; payload: unknown }): PowerAction | null {
  if (kind === "vps") return VPS_POWER[job.type] ?? null;
  if (job.type !== "GAME_POWER") return null;
  const a = (job.payload as { action?: unknown } | null)?.action;
  return a === "start" || a === "stop" || a === "restart" ? a : null;
}

/** "start" → "Start", for buttons and outcome lines. */
export function actionTitle(a: PowerAction): string {
  return a.charAt(0).toUpperCase() + a.slice(1);
}

/** "start" → "Starting", the in-progress label. */
export function actionProgressive(a: PowerAction): string {
  return { start: "Starting", stop: "Stopping", reboot: "Rebooting", restart: "Restarting" }[a];
}

/**
 * Turn the worker's internal `Job.error` into something a customer can act on.
 * The raw strings ("game power: start reported active but port 7777/tcp never
 * bound: timed out", "Proxmox task failed: …") are operator detail — they are
 * matched here, never shown.
 */
export function powerFailureMessage(kind: PowerKind, action: PowerAction, error: string | null): string {
  const e = error ?? "";
  const verb = action;
  if (kind === "game") {
    if (/never bound/i.test(e)) {
      return (
        `The game service ${verb === "stop" ? "stopped" : "came up"}, but the game didn't start answering on its port ` +
        `within our check window. Some games keep loading after that — check the Console tab's log before trying again.`
      );
    }
    if (/no service unit/i.test(e)) return "No game service was found on this server. Open a support ticket and we'll take a look.";
    const state = /state=([a-z-]+)/i.exec(e)?.[1];
    if (state) return `The game service ended up "${state}" instead of running. The Console tab shows its log.`;
    if (/VM is not running/i.test(e)) return "The server itself isn't running, so the game service couldn't be controlled.";
    if (/authentication|ECONNREFUSED|ETIMEDOUT|EHOSTUNREACH|ssh|handshake|timed out/i.test(e)) {
      return `We couldn't reach the server to ${verb} the game. Try again in a minute, or open a support ticket if it keeps happening.`;
    }
    return `The ${verb} didn't complete. Try again, or open a support ticket if it keeps happening.`;
  }
  return `The ${verb} didn't complete. If the server doesn't recover, open a support ticket from this page.`;
}

function view(kind: PowerKind, j: PowerJobRow, action: PowerAction, now: number): PowerJobView {
  const terminal = TERMINAL.has(j.status);
  return {
    id: j.id,
    action,
    status: j.status as PowerJobStatus,
    attempts: j.attempts,
    ageMs: Math.max(0, now - j.createdAt.getTime()),
    finishedAgoMs: terminal ? Math.max(0, now - j.updatedAt.getTime()) : null,
    failure: j.status === "FAILED" ? powerFailureMessage(kind, action, j.error) : null,
  };
}

/**
 * Build the snapshot from the jobs the page already loaded (newest first — the
 * dashboard's `server.jobs` is `orderBy createdAt desc`). One in-flight job per
 * server is enforced server-side, so "the" in-flight job is unambiguous.
 */
export function powerSnapshot(kind: PowerKind, jobs: PowerJobRow[], now: Date = new Date()): PowerSnapshot {
  const t = now.getTime();
  let inflight: PowerJobView | null = null;
  let last: PowerJobView | null = null;
  let blockedBy: string | null = null;
  for (const j of jobs) {
    const action = powerActionOf(kind, j);
    if (IN_FLIGHT.has(j.status)) {
      if (action && !inflight) inflight = view(kind, j, action, t);
      else if (!action && !blockedBy) blockedBy = BLOCKING_LABEL[j.type] ?? "Another operation";
    } else if (action && !last && TERMINAL.has(j.status)) {
      last = view(kind, j, action, t);
    }
  }
  return { inflight, last, blockedBy };
}

