"use client";

import { useCallback, useEffect, useRef, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import type { PowerAction, PowerSnapshot } from "@/lib/power-state";

/**
 * Anti-spam guard for the customer power controls (VPS hero + game hero).
 *
 * Real customers clicked Start/Stop/Restart over and over because nothing said
 * the first click was being worked on (see lib/power-state.ts). This hook is
 * the one place that decides whether power buttons are usable, and why not:
 *
 *   1. SYNCHRONOUS lock on click (a ref, not state) — a second click in the
 *      same frame, before React has re-rendered the button as disabled, is
 *      dropped rather than sent.
 *   2. The action returns the new job's id; the hook then follows THAT job
 *      through the page's real, server-rendered `Job` rows (refreshed by the
 *      page's existing <AutoRefresh/> while anything is in flight) — never a
 *      local timer. A GAME_POWER start legitimately takes from seconds to
 *      several minutes depending on the game (worker/game-control.ts
 *      `powerStartTimeoutMs`), plus up to two worker retries.
 *   3. A job already in flight when the page loads (a reload, another tab, a
 *      scheduled restart) is adopted from the snapshot, so a fresh page never
 *      shows enabled buttons for a server that is mid-action.
 *   4. When the job ends: a clear success/failure outcome, then a short
 *      cooldown before the controls come back, so the reflexive click that
 *      lands the instant the state flips does not fire a new action.
 *
 * The backend guard (`serverAction` / `gamePower`, both now under a per-server
 * advisory lock — lib/job-guard.ts) is still the safety net; this is so the
 * customer never has to meet it.
 */

export const POWER_COOLDOWN_MS = 5_000;
/** A failed job is still worth explaining on a reload for this long. */
const FRESH_FAILURE_MS = 15 * 60_000;
/** Success needs no dismissing; it clears itself. */
const SUCCESS_VISIBLE_MS = 12_000;
/** If the job we queued hasn't shown up in the page data yet, nudge a refresh. */
const UNSEEN_REFRESH_MS = 5_000;
/** ...and stop waiting for one that never appears (never strand the controls). */
const UNSEEN_GIVE_UP_MS = 60_000;

type SendResult =
  | { error?: string; jobId?: string; ok?: boolean }
  | void
  | null
  | undefined;

export type PowerOutcome = {
  jobId: string;
  action: PowerAction;
  ok: boolean;
  /** Customer-safe failure explanation (lib/power-state.ts), null on success. */
  message: string | null;
};

export type PowerGuard = {
  /** Every power button must be disabled while this is true. */
  locked: boolean;
  /** The action being sent or in flight, if any. */
  action: PowerAction | null;
  /** sending = click accepted, waiting on the server; queued/running = real job state. */
  stage: "sending" | "queued" | "running" | null;
  /** Worker attempts on the in-flight job (>1 = retrying). */
  attempts: number;
  /** Seconds since the job was requested — measured, not an estimate. */
  elapsedSec: number | null;
  /** Seconds left in the post-completion cooldown (0 = none). */
  cooldownSec: number;
  outcome: PowerOutcome | null;
  /** The server refused the request (e.g. something else is running). */
  error: string | null;
  /** A non-power job is holding the controls (label for the explanation). */
  blockedBy: string | null;
  run: (action: PowerAction, send: () => Promise<SendResult>) => void;
  dismiss: () => void;
};

export function usePowerGuard(snapshot: PowerSnapshot): PowerGuard {
  const router = useRouter();
  const [pending, startTransition] = useTransition();
  const lock = useRef(false);
  const seen = useRef<Set<string>>(new Set());

  const inflight = snapshot.inflight;
  const last = snapshot.last;

  const [requested, setRequested] = useState<PowerAction | null>(null);
  const [tracked, setTracked] = useState<{ id: string; since: number | null } | null>(() =>
    inflight ? { id: inflight.id, since: null } : null,
  );
  // Seeded from props only (no clock) so server and client render identically.
  const [outcome, setOutcome] = useState<PowerOutcome | null>(() =>
    last && last.status === "FAILED" && last.finishedAgoMs !== null && last.finishedAgoMs < FRESH_FAILURE_MS
      ? { jobId: last.id, action: last.action, ok: false, message: last.failure }
      : null,
  );
  const [cooldownUntil, setCooldownUntil] = useState(0);
  const [error, setError] = useState<string | null>(null);
  // Anchor for the live elapsed counter: the server-measured age at the moment
  // this client received it. Null until mounted, so SSR and hydration agree.
  const [base, setBase] = useState<{ id: string; ageMs: number; at: number } | null>(null);
