/** Success needs no dismissing; it clears itself. */
const SUCCESS_VISIBLE_MS = 12_000;
/** If the job we queued hasn't shown up in the page data yet, nudge a refresh. */
const UNSEEN_REFRESH_MS = 5_000;
/** ...and stop waiting for one that never appears (never strand the controls). */
const UNSEEN_GIVE_UP_MS = 60_000;

type SendResult =
  | { error?: string; jobId?: string; ok?: boolean }
  | void
  | null
  | undefined;

