  /** Every power button must be disabled while this is true. */
  locked: boolean;
  /** The action being sent or in flight, if any. */
  action: PowerAction | null;
  /** sending = click accepted, waiting on the server; queued/running = real job state. */
  stage: "sending" | "queued" | "running" | null;
  /** Worker attempts on the in-flight job (>1 = retrying). */
  attempts: number;
  /** Seconds since the job was requested — measured, not an estimate. */
  elapsedSec: number | null;
  /** Seconds left in the post-completion cooldown (0 = none). */
  cooldownSec: number;
  outcome: PowerOutcome | null;
  /** The server refused the request (e.g. something else is running). */
  error: string | null;
  /** A non-power job is holding the controls (label for the explanation). */
  blockedBy: string | null;
  run: (action: PowerAction, send: () => Promise<SendResult>) => void;
  dismiss: () => void;
