"use client";

import { Icon } from "@/components/nx/Icon";
import { actionProgressive, actionTitle, type PowerAction, type PowerKind } from "@/lib/power-state";
import type { PowerGuard } from "./usePowerGuard";

/**
 * The words under the power buttons. A disabled button with no stated reason is
 * the thing that made customers click again — every locked state here says
 * what is happening and that it is being handled.
 *
 * Honest by construction: the elapsed time is measured from the job's real
 * createdAt, "attempt N" is the worker's real attempt counter, and there is no
 * percentage or ETA because the worker has neither.
 *
 * Two layouts: `strip` (full-width band, the game hero) and `inline` (compact,
 * right-aligned under the VPS hero's buttons). Both sit on the heroes' dark
 * islands, so the colours are the islands' own light-on-dark ones.
 */

function fmtElapsed(sec: number): string {
  if (sec < 60) return `${sec}s`;
  const m = Math.floor(sec / 60);
  const s = sec % 60;
  return `${m}m ${String(s).padStart(2, "0")}s`;
}

function hint(kind: PowerKind, action: PowerAction): string {
  if (kind === "game") {
    return action === "stop"
      ? "Shutting the game service down."
      : "Some games take a few minutes to load their world.";
  }
  if (action === "reboot") return "The server is unreachable until it's back up.";
  if (action === "stop") return "Powering the server off.";
  return "Booting the server.";
}

export function PowerStatusNote({
  guard, kind, layout,
}: {
  guard: PowerGuard;
  kind: PowerKind;
  layout: "strip" | "inline";
}) {
  const strip = layout === "strip";
  const box = strip
    ? "relative mx-5 mb-3 flex items-start gap-2.5 rounded-[10px] border px-3 py-2 text-[12.5px]"
    : "flex max-w-[420px] items-start gap-2 rounded-[10px] border px-2.5 py-1.5 text-left text-[11.5px]";
  const tone = {
    busy: "border-sky-400/30 bg-sky-500/10 text-sky-100",
    ok: "border-emerald-400/30 bg-emerald-500/10 text-emerald-100",
    bad: "border-amber-400/35 bg-amber-500/10 text-amber-100",
    err: "border-rose-400/35 bg-rose-500/10 text-rose-200",
  };
  const iconSize = strip ? 14 : 12;
  const cool = guard.cooldownSec > 0 ? (
    <span className="whitespace-nowrap opacity-70"> · controls back in {guard.cooldownSec}s</span>
  ) : null;

  // 1. In flight (ours, or one already running when the page loaded).
  if (guard.stage && guard.action) {
    const a = guard.action;
    const headline =
      guard.stage === "sending"
        ? `${actionProgressive(a)}…`
        : guard.stage === "queued"
          ? `${actionProgressive(a)} — queued`
          : `${actionProgressive(a)}…`;
    return (
      <div className={`${box} ${tone.busy}`} role="status" aria-live="polite">
        <Icon name="refresh2" size={iconSize} tone="inherit" className="nx-spin mt-[2px] flex-none" />
        <span className="min-w-0">
          <span className="font-bold">{headline}</span>
          {guard.stage === "running" && guard.elapsedSec !== null && (
            <span className="num opacity-80"> {fmtElapsed(guard.elapsedSec)}</span>
          )}
          {guard.attempts > 1 && (
            <span className="opacity-90"> · taking longer than usual, attempt {guard.attempts}</span>
          )}
          <span className="block opacity-80">
            {guard.stage === "sending" ? "Sending the request." : hint(kind, a)} This updates on its own — no need to click again.
          </span>
        </span>
      </div>
    );
  }

  // 2. The server refused the click (something else was already running).
  if (guard.error) {
    return (
      <div className={`${box} ${tone.err}`} role="alert">
        <Icon name="xcircle" size={iconSize} tone="inherit" className="mt-[2px] flex-none" />
        <span className="min-w-0 flex-1">{guard.error}</span>
        <button type="button" onClick={guard.dismiss} className="flex-none font-semibold opacity-70 transition hover:opacity-100">
          Dismiss
        </button>
      </div>
    );
  }

  // 3. How the last action ended.
  if (guard.outcome) {
    const o = guard.outcome;
    if (o.ok) {
      return (
        <div className={`${box} ${tone.ok}`} role="status" aria-live="polite">
          <Icon name="checkcircle" size={iconSize} tone="inherit" className="mt-[2px] flex-none" />
          <span className="min-w-0">
            <span className="font-bold">{actionTitle(o.action)} complete.</span>
            {cool}
          </span>
        </div>
      );
    }
    return (
      <div className={`${box} ${tone.bad}`} role="alert">
        <Icon name="warntriangle" size={iconSize} tone="inherit" className="mt-[2px] flex-none" />
        <span className="min-w-0 flex-1">
          <span className="font-bold">{actionTitle(o.action)} didn&apos;t complete.</span>
          {cool}
          {o.message && <span className="block opacity-85">{o.message}</span>}
        </span>
        <button type="button" onClick={guard.dismiss} className="flex-none font-semibold opacity-70 transition hover:opacity-100">
          Dismiss
        </button>
      </div>
    );
  }

  // 4. A non-power job is holding the controls.
  if (guard.blockedBy) {
    return (
      <div className={`${box} ${tone.busy}`} role="status">
        <Icon name="refresh2" size={iconSize} tone="inherit" className="nx-spin mt-[2px] flex-none" />
        <span className="min-w-0">
          {guard.blockedBy} is in progress — power controls come back when it finishes.
        </span>
      </div>
    );
  }

  return null;
}

