            <span className="opacity-90"> · taking longer than usual, attempt {guard.attempts}</span>
          )}
          <span className="block opacity-80">
            {guard.stage === "sending" ? "Sending the request." : hint(kind, a)} This updates on its own — no need to click again.
          </span>
        </span>
      </div>
    );
  }

  // 2. The server refused the click (something else was already running).
  if (guard.error) {
    return (
      <div className={`${box} ${tone.err}`} role="alert">
        <Icon name="xcircle" size={iconSize} tone="inherit" className="mt-[2px] flex-none" />
        <span className="min-w-0 flex-1">{guard.error}</span>
        <button type="button" onClick={guard.dismiss} className="flex-none font-semibold opacity-70 transition hover:opacity-100">
          Dismiss
        </button>
      </div>
    );
  }

  // 3. How the last action ended.
  if (guard.outcome) {
    const o = guard.outcome;
    if (o.ok) {
      return (
        <div className={`${box} ${tone.ok}`} role="status" aria-live="polite">
          <Icon name="checkcircle" size={iconSize} tone="inherit" className="mt-[2px] flex-none" />
          <span className="min-w-0">
            <span className="font-bold">{actionTitle(o.action)} complete.</span>
            {cool}
          </span>
        </div>
      );
    }
    return (
      <div className={`${box} ${tone.bad}`} role="alert">
        <Icon name="warntriangle" size={iconSize} tone="inherit" className="mt-[2px] flex-none" />
        <span className="min-w-0 flex-1">
          <span className="font-bold">{actionTitle(o.action)} didn&apos;t complete.</span>
          {cool}
          {o.message && <span className="block opacity-85">{o.message}</span>}
        </span>
        <button type="button" onClick={guard.dismiss} className="flex-none font-semibold opacity-70 transition hover:opacity-100">
          Dismiss
        </button>
      </div>
    );
  }

  // 4. A non-power job is holding the controls.
  if (guard.blockedBy) {
    return (
      <div className={`${box} ${tone.busy}`} role="status">
        <Icon name="refresh2" size={iconSize} tone="inherit" className="nx-spin mt-[2px] flex-none" />
        <span className="min-w-0">
          {guard.blockedBy} is in progress — power controls come back when it finishes.
        </span>
      </div>
    );
  }

  return null;
}

