export function VpsPowerControls({ serverId, serverName, status, busy, power, terminalSlot }: {
  serverId: string;
  serverName: string;
  status: string;
  busy: boolean;
  /** Start/Stop/Reboot anti-spam guard, owned by VpsHero (usePowerGuard). */
  power: PowerGuard;
  /** The existing OpenTerminalButton — primary action. */
  terminalSlot: React.ReactNode;
}) {
  const [error, setError] = useState<string | null>(null);
  const [ask, setAsk] = useState<"reinstall" | "delete" | "stop" | null>(null);
  const [pending, start] = useTransition();
  /* Power buttons: the guard locks them the instant one is clicked and keeps
     them locked for the whole life of the real job, then a short cooldown.
     Reinstall/Delete keep their own typed-confirmation path below. */
  const powerDisabled = busy || pending || power.locked;
  const running = status === "RUNNING";

  const runPower = (action: "start" | "stop" | "reboot") =>
    power.run(action, () => serverAction(serverId, action));

  /** Reinstall / Delete — behind typed confirmations, not power actions. */
  const run = (action: "reinstall" | "delete") => {
    setError(null);
    start(async () => {
      const res = await serverAction(serverId, action);
      if (res?.error) setError(res.error);
    });
  };

  /* The clicked button names what it is doing while it does it. */
  const label = (a: "start" | "stop" | "reboot", idle: string) =>
    power.action === a && power.stage ? `${actionProgressive(a)}…` : idle;
  const spinning = (a: "start" | "stop" | "reboot") => power.action === a && !!power.stage;

