164	  useEffect(() => {
165	    if (!tracked || tracked.since === null || inflightId || seen.current.has(tracked.id)) return;
166	    const since = tracked.since;
167	    const t = setInterval(() => {
168	      if (Date.now() - since > UNSEEN_GIVE_UP_MS) {
169	        setTracked(null);
170	        setRequested(null);
171	        lock.current = false;
172	        return;
173	      }
174	      router.refresh();
175	    }, UNSEEN_REFRESH_MS);
176	    return () => clearInterval(t);
177	  }, [tracked, inflightId, router]);
178	
179	  /* Success clears itself; a failure stays until dismissed or the next action. */
180	  useEffect(() => {
181	    if (!outcome?.ok) return;
182	    const id = outcome.jobId;
183	    const t = setTimeout(() => setOutcome((o) => (o?.jobId === id ? null : o)), SUCCESS_VISIBLE_MS);
184	    return () => clearTimeout(t);
185	  }, [outcome]);
186	
