const noteText = async (page) => (await hero(page).innerText()).replace(/\s+/g, " ");

async function vpsBurst(page) {
  const id = fx.vpsId;
  await db.server.update({ where: { id }, data: { status: "RUNNING" } });
  await waitIdle(id);
  await page.goto(`${BASE}/dashboard/servers/${id}`, { waitUntil: "networkidle" });
  await shot(page, "vps-01-idle");
  const t0 = new Date();
  check("vps: sync 10x click dispatched", (await syncBurst(page, "Reboot", 10)) === "ok");
  await sleep(250);
  await shot(page, "vps-02-rebooting");
  const btn = hero(page).getByRole("button", { name: /Reboot/ });
  check("vps: button disabled right after click", await btn.isDisabled());
  await mouseBurst(page, btn, 8, 60);
  const txt = await noteText(page);
  check("vps: in-progress label shown", /Rebooting…/.test(txt), txt.slice(0, 200));
  const jobs = await jobsSince(id, t0);
  check("vps: exactly one REBOOT job from 18 clicks", jobs.length === 1, JSON.stringify(jobs.map((j) => j.type)));
  check("vps: no refusal error shown", !/already running/i.test(await noteText(page)));
  await hero(page).getByText("Reboot complete.").waitFor({ timeout: 30000 });
  await shot(page, "vps-03-complete-cooldown");
  const t1 = Date.now();
  check("vps: controls locked during cooldown", await btn.isDisabled(), await noteText(page).then((s) => s.match(/controls back in \d+s/)?.[0] ?? ""));
  await page.waitForFunction(() => {
    const b = [...document.querySelectorAll("header.nx-dark-island button")].find((x) => x.textContent.trim() === "Reboot");
    return b && !b.disabled;
  }, null, { timeout: 15000 });
  check("vps: controls return after cooldown", true, `${((Date.now() - t1) / 1000).toFixed(1)}s after the outcome appeared`);
  await shot(page, "vps-04-ready-again");
}

async function vpsPaused(page) {
  const id = fx.vpsId;
  await waitIdle(id);
  await page.goto(`${BASE}/dashboard/servers/${id}`, { waitUntil: "networkidle" });
  execSync("systemctl stop nxeon-staging-worker");
  log("staging worker STOPPED (job will sit QUEUED)");
  try {
    const t0 = new Date();
    await hero(page).getByRole("button", { name: /^\s*Stop\s*$/ }).click();
    await page.getByRole("button", { name: "Stop server" }).click();
    await sleep(1500);
    await shot(page, "vps-05-stop-queued");
    check("vps(paused): queued label", /Stopping — queued/.test(await noteText(page)), (await noteText(page)).slice(0, 220));
    await page.reload({ waitUntil: "networkidle" });
    await shot(page, "vps-06-stop-queued-after-reload");
    const txt = await noteText(page);
    check("vps(paused): in-flight job adopted on reload", /Stopping/.test(txt) && /Stopping…/.test(txt), txt.slice(0, 220));
    const stopBtn = hero(page).getByRole("button", { name: /Stop/ }).first();
    check("vps(paused): Stop disabled after reload", await stopBtn.isDisabled());
    await mouseBurst(page, stopBtn, 6, 80);
    check("vps(paused): no Confirm dialog opened by extra clicks", !(await page.getByRole("button", { name: "Stop server" }).isVisible().catch(() => false)));
    const jobs = await jobsSince(id, t0);
    check("vps(paused): exactly one STOP job", jobs.length === 1 && jobs[0].type === "STOP", JSON.stringify(jobs));
  } finally {
    execSync("systemctl start nxeon-staging-worker");
    log("staging worker STARTED");
  }
  await hero(page).getByText("Stop complete.").waitFor({ timeout: 45000 });
  await shot(page, "vps-07-stop-complete");
  const startBtn = hero(page).getByRole("button", { name: /Start/ });
  check("vps: Start shown + locked during cooldown after stop", await startBtn.isDisabled());
  await page.waitForFunction(() => {
    const b = [...document.querySelectorAll("header.nx-dark-island button")].find((x) => x.textContent.trim() === "Start");
    return b && !b.disabled;
  }, null, { timeout: 15000 });
  // restore RUNNING via a real Start
  await startBtn.click();
  await hero(page).getByText("Start complete.").waitFor({ timeout: 30000 });
  check("vps: real Start completes", true);
}

async function gameBurst(page) {
  const id = fx.gameId;
  await waitIdle(id);
  const s = await db.server.findUnique({ where: { id }, select: { gameConfig: true } });
  await db.server.update({ where: { id }, data: { gameConfig: { ...(s.gameConfig ?? {}), _serviceState: "active" } } });
  await page.goto(`${BASE}/dashboard/servers/${id}`, { waitUntil: "networkidle" });
  await shot(page, "game-01-idle");
  const t0 = new Date();
  check("game: sync 10x Restart dispatched", (await syncBurst(page, "Restart", 10)) === "ok");
  await sleep(250);
  await shot(page, "game-02-restarting");
  const btn = hero(page).getByRole("button", { name: /Restart/ });
  check("game: Restart disabled right after click", await btn.isDisabled());
  await mouseBurst(page, btn, 8, 60);
  await mouseBurst(page, hero(page).getByRole("button", { name: /Stop/ }), 4, 60);
  const jobs = await jobsSince(id, t0);
  check("game: exactly one GAME_POWER job from 22 clicks", jobs.length === 1 && jobs[0].type === "GAME_POWER", JSON.stringify(jobs.map((j) => [j.type, j.payload])));
  await hero(page).getByText("Restart complete.").waitFor({ timeout: 30000 });
  await shot(page, "game-03-restart-complete");
}

async function gameInflight(page) {
  const id = fx.gameId;
  await waitIdle(id);
  const s = await db.server.findUnique({ where: { id }, select: { gameConfig: true } });
  await db.server.update({ where: { id }, data: { gameConfig: { ...(s.gameConfig ?? {}), _serviceState: "inactive" } } });
  // A start already 95s in and on its 2nd worker attempt when the page loads —
  // exactly the Terraria shape. RUNNING rows are never claimed by the worker loop.
  const job = await db.job.create({
    data: { type: "GAME_POWER", serverId: id, status: "RUNNING", attempts: 2, payload: { action: "start", announce: false },
            error: "game power: start reported active but port 25565/tcp never bound: timed out",
            createdAt: new Date(Date.now() - 95_000) },
  });
  try {
    await page.goto(`${BASE}/dashboard/servers/${id}`, { waitUntil: "networkidle" });
    await shot(page, "game-04-start-inflight-on-load");
    const txt = await noteText(page);
    check("game: in-flight start adopted on load", /Starting…/.test(txt) && /1m 3\ds/.test(txt) && /attempt 2/.test(txt), txt.slice(0, 260));
    const t0 = new Date();
    for (const name of [/Start/, /Restart/, /Stop/]) {
      const b = hero(page).getByRole("button", { name }).first();
      check(`game: ${name.source} disabled while job runs`, await b.isDisabled());
      await mouseBurst(page, b, 4, 50);
    }
    check("game: no jobs created by clicks during in-flight", (await jobsSince(id, t0)).length === 0);
    await sleep(3000);
    const txt2 = await noteText(page);
    check("game: elapsed counter ticks", /1m 3\ds|1m 4\ds/.test(txt2), txt2.match(/Starting… [^A-Z]*/)?.[0] ?? "");
  } finally {
    await db.job.update({ where: { id: job.id }, data: { status: "FAILED", attempts: 3 } });
  }
  await hero(page).getByText("Start didn't complete.").waitFor({ timeout: 20000 });
  await shot(page, "game-05-start-failed");
  check("game: failure reason is customer-safe", !/never bound|25565\/tcp/.test(await noteText(page)), (await noteText(page)).match(/Start didn't complete\.[^]*?Dismiss/)?.[0] ?? "");
  await page.reload({ waitUntil: "networkidle" });
  check("game: failure still explained after reload", /Start didn't complete/.test(await noteText(page)));
  await shot(page, "game-06-failed-after-reload");
  await hero(page).getByRole("button", { name: "Dismiss" }).click();
  check("game: Dismiss clears it", !/Start didn't complete/.test(await noteText(page)));
}

async function gameBlocked(page) {
  const id = fx.gameId;
  await waitIdle(id);
  const job = await db.job.create({ data: { type: "GAME_BACKUP", serverId: id, status: "RUNNING", attempts: 1 } });
  try {
    await page.goto(`${BASE}/dashboard/servers/${id}`, { waitUntil: "networkidle" });
    await shot(page, "game-07-blocked-by-backup");
    check("game: blocked-by label", /A world backup is in progress/.test(await noteText(page)));
  } finally {
    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
  }
}

async function mobile(browser) {
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
  const page = await ctx.newPage();
  await login(page);
  for (const [key, id, type, action] of [["vps", fx.vpsId, "REBOOT", null], ["game", fx.gameId, "GAME_POWER", "restart"]]) {
    await waitIdle(id);
    const job = await db.job.create({ data: { type, serverId: id, status: "RUNNING", attempts: 1, payload: action ? { action } : undefined, createdAt: new Date(Date.now() - 12_000) } });
    try {
      await page.goto(`${BASE}/dashboard/servers/${id}`, { waitUntil: "networkidle" });
      await shot(page, `mobile-${key}-inflight`);
      const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
      check(`mobile ${key}: no horizontal overflow`, overflow <= 0, `overflow=${overflow}px`);
    } finally {
      await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
    }
  }
  await ctx.close();
}

async function light(page) {
  const id = fx.vpsId;
  await waitIdle(id);
  const job = await db.job.create({ data: { type: "REBOOT", serverId: id, status: "RUNNING", attempts: 1, createdAt: new Date(Date.now() - 7_000) } });
  try {
    await page.goto(`${BASE}/dashboard/servers/${id}`, { waitUntil: "networkidle" });
    await page.evaluate(() => document.documentElement.setAttribute("data-theme", "light"));
    await sleep(400);
    await shot(page, "vps-light-inflight");
  } finally {
    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
  }
}

const steps = process.argv.slice(2);
const browser = await chromium.launch();
try {
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1.5 });
  const page = await ctx.newPage();
  page.on("pageerror", (e) => log("PAGE ERROR", e.message));
  page.on("console", (m) => { if (m.type() === "error" && !/favicon|Failed to load resource/.test(m.text())) log("console.error", m.text().slice(0, 200)); });
  await login(page);
  for (const s of steps) {
    log("=== step", s);
    if (s === "vps-burst") await vpsBurst(page);
    else if (s === "vps-paused") await vpsPaused(page);
    else if (s === "game-burst") await gameBurst(page);
    else if (s === "game-inflight") await gameInflight(page);
    else if (s === "game-blocked") await gameBlocked(page);
    else if (s === "mobile") await mobile(browser);
    else if (s === "light") await light(page);
  }
} finally {
  await browser.close();
  await db.$disconnect();
  const failed = results.filter((r) => !r.ok);
  console.log(`\n${results.length - failed.length}/${results.length} checks passed`);
  for (const f of failed) console.log("FAILED:", f.name, f.detail);
}

