/* Follow the job through the page's real data. */
useEffect(() => {
  if (inflight) {
    seen.current.add(inflight.id);
    setTracked((t) => (t?.id === inflight.id ? t : { id: inflight.id, since: null }));
    setRequested(null); // handed off — the real job speaks for itself now
    return;
  }
  if (!tracked) return;
  const resolved = last && last.id === tracked.id;
  // Seen in flight, now neither in flight nor the latest finished power job:
  // it ended and something newer already finished after it. Release.
  const superseded = !resolved && seen.current.has(tracked.id);
  if (resolved || superseded) {
    if (resolved && last) {
      setOutcome({ jobId: last.id, action: last.action, ok: last.status === "DONE", message: last.failure });
    }
    setCooldownUntil(Date.now() + POWER_COOLDOWN_MS);
    setTracked(null);
    setRequested(null);
    lock.current = false;
  }
  // eslint-disable-next-line react-hooks/exhaustive-deps -- keyed on ids/status, not object identity
}, [inflightId, lastId, lastStatus, tracked?.id]);

