// Admin PowerActions check against THIS box's staging (the public
// "staging admin" hostname proxies to node-2, a different app + DB).
// Logs in on the customer host as the fixture user (temporarily ADMIN), then
// loads /admin/servers/<id> through a route that forwards to 127.0.0.1:3001
// with the admin Host header, so the real staging build renders it.
import { createRequire } from "node:module";
import { readFileSync } from "node:fs";
const require = createRequire("/opt/nxeon/package.json");
const { chromium } = require("playwright");
const { PrismaClient } = require("@prisma/client");
const DIR = new URL(".", import.meta.url).pathname;
const fx = JSON.parse(readFileSync(DIR + "pd-fixture.json", "utf8"));
const env = readFileSync("/opt/nxeon-staging/.env", "utf8");
const url = /^DATABASE_URL=(.*)$/m.exec(env)[1].trim().replace(/^"|"$/g, "");
if (!/nxeon_staging/.test(url)) throw new Error("not staging");
const db = new PrismaClient({ datasources: { db: { url } } });
const ADMIN_HOST = "staging.4j3d7gkr2wcbi34.nxeon.cloud";
const results = [];
const check = (n, ok, d = "") => { results.push(ok); console.log(ok ? "PASS" : "FAIL", n, d); };

await db.user.update({ where: { email: fx.email }, data: { role: "ADMIN" } });
const browser = await chromium.launch();
let job = null;
try {
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1.5 });
  const page = await ctx.newPage();
  await page.goto("https://staging.nxeon.cloud/login", { waitUntil: "domcontentloaded" });
  await page.fill("#login-email", fx.email);
  await page.fill("#login-password", fx.password);
  await Promise.all([page.waitForURL((u) => !u.pathname.startsWith("/login"), { timeout: 30000 }), page.click("button.btn-primary")]);
  const cookies = (await ctx.cookies()).filter((c) => c.domain.includes("staging.nxeon.cloud"));
  await ctx.addCookies(cookies.map((c) => ({ ...c, domain: ADMIN_HOST })));
  await ctx.route(`https://${ADMIN_HOST}/**`, async (route) => {
    const req = route.request();
    const target = req.url().replace(`https://${ADMIN_HOST}`, "http://127.0.0.1:3001");
    const resp = await route.fetch({ url: target, headers: { ...req.headers(), host: ADMIN_HOST, "x-forwarded-proto": "https", "x-forwarded-host": ADMIN_HOST }, maxRedirects: 0 });
    await route.fulfill({ response: resp });
  });
  const card = page.locator(".card", { has: page.getByRole("heading", { name: "Admin actions" }) });
  await page.goto(`https://${ADMIN_HOST}/admin/servers/${fx.vpsId}`, { waitUntil: "networkidle" });
  console.log("landed:", page.url(), "| title:", await page.title());
  check("admin: Reboot enabled when idle", !(await card.getByRole("button", { name: "Reboot" }).isDisabled()));
  await card.screenshot({ path: DIR + "shots/admin-idle.png" });
  job = await db.job.create({ data: { type: "REBOOT", serverId: fx.vpsId, status: "RUNNING", attempts: 1 } });
  await page.goto(`https://${ADMIN_HOST}/admin/servers/${fx.vpsId}`, { waitUntil: "networkidle" });
  await card.screenshot({ path: DIR + "shots/admin-inflight.png" });
  const txt = (await card.innerText()).replace(/\s+/g, " ");
  check("admin: Start/Stop/Reboot disabled while a job is in flight",
    (await card.getByRole("button", { name: "Reboot" }).isDisabled()) && (await card.getByRole("button", { name: "Stop" }).isDisabled()) && (await card.getByRole("button", { name: "Start" }).isDisabled()));
  check("admin: in-flight job named", /REBOOT job running — power controls return when it finishes/.test(txt), txt.slice(0, 180));
  await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
  job = null;
  await page.waitForFunction(() => {
    const c = [...document.querySelectorAll(".card")].find((x) => x.querySelector("h2")?.textContent === "Admin actions");
    const b = c && [...c.querySelectorAll("button")].find((x) => x.textContent.trim() === "Reboot");
    return b && !b.disabled;
  }, null, { timeout: 20000 });
  check("admin: re-enabled by the page's AutoRefresh once the job ends (no cooldown)", true);
} finally {
  if (job) await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
  await db.user.update({ where: { email: fx.email }, data: { role: "CUSTOMER" } });
  console.log("fixture user role reverted to CUSTOMER");
  await browser.close();
  await db.$disconnect();
  console.log(`${results.filter(Boolean).length}/${results.length} admin checks passed`);
}

